#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string line;
    getline(cin, line); // read first line and ignore
    getline(cin, line); // read second line which contains data

    // Split data by pattern "\([a-zA-Z_]*\)"
    vector<string> segments;
    regex re("\\([a-zA-Z_]*\\)");
    sregex_token_iterator it(line.begin(), line.end(), re, -1);
    sregex_token_iterator end;
    for (; it != end; ++it) {
        segments.push_back(it->str());
    }

    int maxWordLength = 0;
    for (const auto& segment : segments) {
        // Split segment by underscores
        stringstream ss(segment);
        string word;
        while (getline(ss, word, '_')) {
            maxWordLength = max(maxWordLength, (int)word.length());
        }
    }

    int countLetters = 0;
    int letterCount = 0;
    bool insideBracket = false;
    bool countedLetter = false;

    for (char c : line) {
        if (c == '(') {
            insideBracket = true;
        } else if (c == ')') {
            countedLetter = false;
            insideBracket = false;
        } else if (insideBracket && isalpha(c)) {
            if (countedLetter) continue;
            countLetters++;
            countedLetter = true;
        } else if (c == '_') {
            countedLetter = false;
        }
    }

    cout << maxWordLength << " " << countLetters << "\n";

    return 0;
}
